BEGIN;
CREATE TABLE IF NOT EXISTS public.partner_registration_applications (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), application_type TEXT NOT NULL CHECK (application_type IN ('travel','vendor')), user_id UUID NOT NULL REFERENCES public.users(id), payload JSONB NOT NULL CHECK (jsonb_typeof(payload)='object'), status TEXT NOT NULL DEFAULT 'submitted' CHECK (status IN ('draft','submitted','under_review','revision_required','approved','rejected')), reviewer_user_id UUID REFERENCES public.users(id), review_note TEXT, organization_id UUID REFERENCES public.organizations(id), submitted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS partner_registration_active_idx ON public.partner_registration_applications(user_id,application_type) WHERE status IN ('draft','submitted','under_review','revision_required');
CREATE TABLE IF NOT EXISTS public.registration_documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), application_id UUID NOT NULL REFERENCES public.partner_registration_applications(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES public.users(id), document_type TEXT NOT NULL, storage_key TEXT NOT NULL UNIQUE, original_name TEXT NOT NULL, mime_type TEXT NOT NULL, byte_size INTEGER NOT NULL CHECK (byte_size > 0 AND byte_size <= 4194304), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.partner_registration_events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), application_id UUID NOT NULL REFERENCES public.partner_registration_applications(id) ON DELETE CASCADE, actor_user_id UUID REFERENCES public.users(id), from_status TEXT, to_status TEXT NOT NULL, note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO public.schema_migrations(version) VALUES ('0038_partner_registration_applications') ON CONFLICT (version) DO NOTHING;
COMMIT;
